sys_ui_action.client_script_v2:
function onClick(g_form) {
    var ga = new GlideAjax('x_fub_fundbrad_ev.EvRetomarAtendimentoAjax');

    ga.addParam('sysparm_name', 'retomar');
    ga.addParam('sysparm_record_id', g_form.getUniqueValue());

    ga.getXMLAnswer(function (answer) {
        var response;

        try {
            response = JSON.parse(answer || '{}');
        } catch (error) {
            g_form.addErrorMessage('Resposta inválida do servidor.');
            return;
        }

        if (!response || response.success !== true) {
            g_form.addErrorMessage(
                (response && response.error) || 'Não foi possível retomar o atendimento.'
            );
            return;
        }

        g_form.addInfoMessage('Atendimento retomado com sucesso.');
        g_form.reload();
    });
}

sys_ui_action.script:
var evRetomandoAtendimento = false;

function retomarAtendimento() {
    if (evRetomandoAtendimento) return false;

    evRetomandoAtendimento = true;

    var ga = new GlideAjax('x_fub_fundbrad_ev.EvRetomarAtendimentoAjax');

    ga.addParam('sysparm_name', 'retomar');
    ga.addParam('sysparm_record_id', g_form.getUniqueValue());

    ga.getXMLAnswer(function(answer) {
        var response;

        try {
            response = JSON.parse(answer || '{}');
        } catch (error) {
            response = { error: 'Resposta inválida do servidor.' };
        }

        if (!response || response.success !== true) {
            evRetomandoAtendimento = false;
            g_form.addErrorMessage(
                (response && response.error) || 'Não foi possível retomar o atendimento.'
            );
            return;
        }

        window.location.reload();
    });

    return false;
}
